{"id": "kz.bozshakol:advisor", "attributes": {"name": "Советник диспетчера", "kind": "advisor", "_isType": false, "_parents": "kz.bozshakol:mine", "rules": "crusher, clay, plan, inflow, fleet, blizzard", "service": "bz-advisor", "reality": "сверка с реальностью: core/reality.py, источники — data/SOURCES.md", "type": "kz.bozshakol.types:advisor"}, "features": {"advice": {"value": "[{\"id\": \"fleet\", \"priority\": \"important\", \"level\": 1, \"title\": \"Лишние самосвалы\", \"text\": \"Ожидание у экскаватора 2.8 мин при ориентире 1.2 мин. Лишних самосвалов ≈ 4 — поставить в резерв (стоянка у заправки).\", \"reason\": \"среднее ожидание у экскаватора 2.8 мин — больше 2 мин в режиме «авто»; модуль транспорта: в работе (в цикле) 25, нужно ≈ 21.3, в резерве уже 3\", \"effect\": \"ожидание у экскаватора снизится к 1.2 мин, расход топлива и износ — меньше на ≈ 4 машины\", \"target\": \"kz.bozshakol:excavator-03\", \"data\": {\"dispatch.avg_wait_excavator\": 2.79, \"dispatch.trucks_hauling\": 16, \"excavator_queue_total\": 2, \"excavators_working\": 6, \"reserve_estimate\": 4}}, {\"id\": \"inflow\", \"priority\": \"info\", \"level\": 0, \"title\": \"Привоз руды ниже плана\", \"text\": \"Привоз руды на дробилку за последний час — 86 % плана (2906 из 3361 т/ч); фабрика идёт со склада, его хватит на 3.3 ч. Узкое место: цикл экскаватора (ожидание/погрузка у экскаватора), а не число самосвалов — самосвалы ждут у экскаваторов 2.8 мин; погрузка медленнее в face-05 (loading_factor 0.86), face-06 (loading_factor 0.86).\", \"reason\": \"средний привоз на склад крупнодроблёной руды за последний модельный час против плана фабрики; цикл экскаватора (ожидание/погрузка у экскаватора), а не число самосвалов — самосвалы ждут у экскаваторов 2.8 мин; погрузка медленнее в face-05 (loading_factor 0.86), face-06 (loading_factor 0.86)\", \"effect\": \"привоз вернётся к плану 3361 т/ч, склад перестанет таять\", \"target\": \"kz.bozshakol:excavator-03\", \"data\": {\"inflow_pct_hour\": 86.5, \"inflow_avg\": 2905.9, \"plan_rate\": 3361.0, \"stockpile-coarse.hours_left\": 3.3, \"causes\": [\"цикл экскаватора (ожидание/погрузка у экскаватора), а не число самосвалов — самосвалы ждут у экскаваторов 2.8 мин; погрузка медленнее в face-05 (loading_factor 0.86), face-06 (loading_factor 0.86)\"]}}]", "unit": "json"}, "advice_count": {"value": 2, "unit": "шт"}, "top_advice": {"value": "Ожидание у экскаватора 2.8 мин при ориентире 1.2 мин. Лишних самосвалов ≈ 4 — поставить в резерв (стоянка у заправки)."}, "level": {"value": 1}, "advice_ids": {"value": "fleet,inflow"}, "reality": {"value": "{\"rows\": [{\"id\": \"feed_sulphide\", \"name\": \"Руда на сульфидную фабрику\", \"unit\": \"т/ч\", \"real\": 3360, \"real_range\": null, \"model\": 3360.7, \"dev_pct\": 0.0, \"source\": \"KAZ Minerals, Q4 2025 Production report — https://www.kazminerals.com/app/uploads/2026/02/Q4-2025-Production-report_FINAL_ENG.pdf; расчёт: (35,7 − 6,26) млн т / 8 760 ч\", \"model_from\": \"plant-sulphide.feed_rate\", \"calibrated\": true, \"status\": \"ok\"}, {\"id\": \"feed_clay\", \"name\": \"Руда на фабрику глинистой руды\", \"unit\": \"т/ч\", \"real\": 715, \"real_range\": null, \"model\": 714.6, \"dev_pct\": -0.1, \"source\": \"KAZ Minerals, Q4 2025 Production report — https://www.kazminerals.com/app/uploads/2026/02/Q4-2025-Production-report_FINAL_ENG.pdf; расчёт: 6,26 млн т / 8 760 ч\", \"model_from\": \"plant-clay.feed_rate\", \"calibrated\": true, \"status\": \"ok\"}, {\"id\": \"cu_grade\", \"name\": \"Содержание меди в питании\", \"unit\": \"% Cu\", \"real\": 0.39, \"real_range\": null, \"model\": 0.379, \"dev_pct\": -2.8, \"source\": \"KAZ Minerals, Q4 2025 Production report — https://www.kazminerals.com/app/uploads/2026/02/Q4-2025-Production-report_FINAL_ENG.pdf\", \"model_from\": \"feed_cu обеих фабрик, взвешено по feed_rate\", \"calibrated\": false, \"status\": \"ok\"}, {\"id\": \"recovery\", \"name\": \"Извлечение меди\", \"unit\": \"%\", \"real\": 73.4, \"real_range\": null, \"model\": 72.273, \"dev_pct\": -1.5, \"source\": \"KAZ Minerals, Q4 2025 Production report — https://www.kazminerals.com/app/uploads/2026/02/Q4-2025-Production-report_FINAL_ENG.pdf\", \"model_from\": \"медь в концентрат / медь в питании по обеим фабрикам (feed_rate × feed_cu × recovery)\", \"calibrated\": false, \"status\": \"ok\"}, {\"id\": \"cu_kt_year\", \"name\": \"Медь в концентрате, темп года\", \"unit\": \"тыс. т/год\", \"real\": 102, \"real_range\": null, \"model\": 97.772, \"dev_pct\": -4.1, \"source\": \"KAZ Minerals, Q4 2025 Production report — https://www.kazminerals.com/app/uploads/2026/02/Q4-2025-Production-report_FINAL_ENG.pdf; расчёт: 35,7 млн т × 0,39 % × 73,4 % ≈ 102 тыс. т\", \"model_from\": \"cu_year_pace обеих фабрик\", \"calibrated\": false, \"status\": \"ok\"}, {\"id\": \"wait_excavator\", \"name\": \"Ожидание самосвала у экскаватора (режим «авто»)\", \"unit\": \"мин\", \"real\": null, \"real_range\": [1.0, 1.5], \"model\": 1.846, \"dev_pct\": 23.1, \"source\": \"im-mining.com, 28.03.2025 — https://im-mining.com/2025/03/28/hexagons-fleet-and-fatigue-management-in-tandem-at-bozshakol/ (было 3–5 мин до диспетчеризации)\", \"model_from\": \"dispatch.avg_wait_excavator\", \"calibrated\": false, \"status\": \"off\"}, {\"id\": \"energy_kwh_t\", \"name\": \"Удельная электроэнергия фабрики\", \"unit\": \"кВт·ч/т\", \"real\": null, \"real_range\": [26.9, 36.3], \"model\": 29.1, \"dev_pct\": 0.0, \"source\": \"Справочник НДТ РК 2023 (zakon.uchet.kz, документ P2300001101), табл. 1.4, п. 4.6: Бозшакольская обогатительная фабрика — 26,85–36,33 кВт·ч/т\", \"model_from\": \"plant-sulphide.specific_energy — удельный расход сульфидной фабрики за смену (модуль переработки)\", \"calibrated\": false, \"status\": \"ok\"}], \"window_min\": 60.0, \"warmup\": false}", "unit": "json"}, "reality_warmup": {"value": false}, "real_window_min": {"value": 60.0, "unit": "мин"}, "real_feed_sulphide": {"value": 3360.7, "unit": "т/ч"}, "real_feed_clay": {"value": 714.6, "unit": "т/ч"}, "real_cu_grade": {"value": 0.379, "unit": "% Cu"}, "real_recovery": {"value": 72.273, "unit": "%"}, "real_cu_kt_year": {"value": 97.772, "unit": "тыс. т/год"}, "real_wait_excavator": {"value": 1.846, "unit": "мин"}, "real_energy_kwh_t": {"value": 29.1, "unit": "кВт·ч/т"}}}
